INTERPRETER='/disk/10tb/home/shmelev/miniconda3/envs/rapids-25.06/bin/python3.12'
assert subprocess.run(['git','rev-parse','--show-toplevel'],cwd=REPO,capture_output=True,text=True,check=True).stdout.strip()==str(REPO)
uuids=subprocess.run(['nvidia-smi','--query-gpu=uuid','--format=csv,noheader'],capture_output=True,text=True,check=True).stdout.splitlines()
assert set(uuids)=={'GPU-98aa0f2e-3dd1-5cd8-f001-f259f707a998','GPU-5dcf7db7-a450-3ca8-41b2-6c5316128ced'}
assert hashlib.sha256(Path(INTERPRETER).read_bytes()).hexdigest()=='14776d98474f987919376922a9995a20733e13b51d7d122873b068bf2e47d1b2'
assert hashlib.sha256((SOURCE/'MANIFEST.json').read_bytes()).hexdigest()=='a99b0e3b0e8ec597b03e2c390ac176597b5b6422d365fc20624ab98a113d42f9'
for e in json.loads((SOURCE/'MANIFEST.json').read_text())['files']:
    p=SOURCE/e['path']
    assert p.stat().st_size==e['bytes'] and hashlib.sha256(p.read_bytes()).hexdigest()==e['sha256']
assert hashlib.sha256((PHASE/'source_model_gauge_probe_20261003_v1/WITNESS.json').read_bytes()).hexdigest()=='9a6a738fa48816300b574cba57851d31831004867b1a6f9acf24346e79255bef'
source=base64.b64decode('')
assert hashlib.sha256(source).hexdigest()=='71734c319523e7537ad15153b497fc2c006ac8c038040380606f2e787688dda8'
compile(source,str(OUT/'recheck.py'),'exec')
OUT.mkdir(exist_ok=False)
(OUT/'recheck.py').write_bytes(source)
started=datetime.now(timezone.utc).isoformat(); start=time.monotonic()
result=subprocess.run([INTERPRETER,'-B',str(OUT/'recheck.py')],cwd=REPO,capture_output=True,text=True,timeout=80)
