record=dict(schema='gauge-byte-recheck-execution-v1',UTC_started=started,UTC_finished=datetime.now(timezone.utc).isoformat(),elapsed_seconds=time.monotonic()-start,argv=[INTERPRETER,'-B',str(OUT/'recheck.py')],cwd=str(REPO),executed_recheck_sha256='71734c319523e7537ad15153b497fc2c006ac8c038040380606f2e787688dda8',exit_code=result.returncode,env_overrides={},isolation_wrapper=False,base_environment_changed=False,normal_CPU_fixture_execution=True,remote_writes_scope=str(OUT),originals_modified=False)
if (OUT/'RECHECK.json').exists():
    raw=(OUT/'RECHECK.json').read_bytes(); record['result_sha256']=hashlib.sha256(raw).hexdigest(); record['result_bytes']=len(raw)
(OUT/'EXECUTION.json').write_text(json.dumps(record,indent=2)+'\n')
print(json.dumps(dict(execution=record,fixture_summary=result.stdout.strip(),stderr=result.stderr)))
raise SystemExit(result.returncode)
